SELECT p.id AS position_id, s.id, s.interval_code, s.candle_open_time, s.generated_at, s.signal_mode, s.decision, s.original_decision, s.total_score, s.confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.data_quality_valid, s.latest_price FROM paper_position p JOIN trade_signal s ON s.symbol = p.symbol AND s.interval_code IN ('5m','1h') AND s.generated_at BETWEEN p.opened_at - INTERVAL 2 HOUR AND p.closed_at + INTERVAL 1 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.interval_code, s.generated_at LIMIT 400;